"""BetterAgent: SimplifyAgent plus six switchable additions (each a small method, off by its class constant).

0. GUARD_C_OPEN (bug fix). Real P02 (v17) closed at c_deal 2,291,903 > c_open 2,282,867 (score 0). Cause: in a
   strategic / bottleneck case C charges for the supplier's margin below `sustainable_margin_pct` (here 140k at the
   deal), but `total_cost` without a supplier estimate sees 0, so simplify's closing rule and caps (all plain C)
   found 345.51 clearly cheaper than the 370.96 opening. Fix: every decision is re-checked with C that includes an
   estimated relationship cost (full cost = the opening quote less the sustainable margin: the opening is assumed
   to sit at the floor, the conservative reading); a sheet or accept above c_open gets its price raised until it fits.
1. THIRD_SHEET: a third equivalent sheet (shorter payment or another contract length, price lowered to equal C).
2. ANCHOR_BY_SHARE: first offer = max(floor, price x (1 - share x index drop)) where the case data show a drop.
3. CASH_SHORT: a cash-short supplier gets shorter payment days against a lower price.
4. LATE_ACCEPT: with <= 2 messages left, accept a standing sheet within 1% of the best known C.
Rival-quote citation (RESEARCH rule 12) is not here: EvidenceAgent._rewrite already cites the best real rival offer ID."""

import math
import re

from ..cost import closing_terms, complete_offer, must_haves_ok, supplier_value, total_cost
from ..docs import standard_terms
from ..guard import satisfy_must_haves
from ..play import find_sheet, moves_left, standing
from .reciprocal import ANCHOR_FLOOR, _c_alt, _live, _mine, _pinned, _sheets, _sup
from .simplify_agent import FREE_LEVERS, SimplifyAgent, _health_at_stake

CASH_SHORT = re.compile(r"liquidity|working[- ]capital|cash[- ]?flow|short of cash|cash[- ]?(?:tight|short|constrain|crunch)", re.I)


class BetterAgent(SimplifyAgent):
    GUARD_C_OPEN = THIRD_SHEET = ANCHOR_BY_SHARE = CASH_SHORT_OFFER = LATE_ACCEPT = True
    LATE_MESSAGES, LATE_TOLERANCE = 2, 0.01

    def decide(self, case, threads):
        if self.LATE_ACCEPT and (late := self._late_accept(case, threads)):
            return self._guard(case, threads, late)
        return self._guard(case, threads, super().decide(case, threads))

    # 0. never offer or accept above c_open ------------------------------------------------------------------
    @staticmethod
    def _est_c(case, events, t, std):
        """C of a sheet, with the supplier's margin priced when the case charges for it."""
        supplier = None
        if _health_at_stake(case) and case["buyer"].get("sustainable_margin_pct"):
            try:
                first = next(m["term_sheets"][0]["terms"] for m in _sup(events) if m.get("term_sheets"))
                # the quote PDF may be missing: the opening sheet then stands in for the standard terms
                s = {"standard": closing_terms(case, first, std), "interest_rate": case["buyer"]["interest_rate"]}
                s["full_cost"] = supplier_value(case, first, s) * (1 - case["buyer"]["sustainable_margin_pct"] / 100)
                supplier = s
            except Exception:  # no usable opening / standard terms: plain C
                supplier = None
        return total_cost(case, t, std, supplier=supplier)

    def _open_c(self, case, threads):
        out = math.inf
        for ev in threads.values():
            std = standard_terms(ev)
            for m in _sup(ev):
                if m.get("term_sheets"):
                    for s in m["term_sheets"]:
                        t = s.get("terms") or {}
                        if t.get("unit_price") is not None and must_haves_ok(case, t, std):
                            out = min(out, self._est_c(case, ev, t, std))
                    break
        return out

    def _repair(self, case, events, std, t, c_open, top):
        """The sheet with the lowest price >= its own at which C <= c_open (up to `top`), else None."""
        if self._est_c(case, events, t, std) <= c_open:
            return t
        lo = t["unit_price"]
        for i in range(1, 101):
            v = {**t, "unit_price": round(lo + (top - lo) * i / 100, 2)}
            if self._est_c(case, events, v, std) <= c_open:
                return v
        return None

    def _guard(self, case, threads, d):
        if not self.GUARD_C_OPEN:
            return d
        sid, msg = d.get("supplier_id"), d.get("message") or {}
        ev = threads.get(sid)
        if not ev:
            return d
        std, c_open = standard_terms(ev), self._open_c(case, threads)
        act = msg.get("action") or {}
        if act.get("type") == "accept":
            theirs = find_sheet(ev, act.get("term_sheet_id"))
            if theirs is None or self._est_c(case, ev, theirs, std) <= c_open:
                return d
            base = {k: std[k] for k in case["negotiable"] if k in std}
            sheets = [complete_offer(case, {**base, **theirs})]
        elif msg.get("term_sheets"):
            sheets = [s["terms"] for s in msg["term_sheets"]]
        else:
            return d
        first = next((m["term_sheets"][0]["terms"]["unit_price"] for m in _sup(ev) if m.get("term_sheets")), 0)
        fixed = [r for t in sheets if (r := self._repair(case, ev, std, t, c_open, max(first, t["unit_price"])))]
        if fixed == sheets:
            return d
        body = {"subject": case.get("title", "Our proposal"), "body": "Thank you for your offer. Please see our updated terms."}
        return {"supplier_id": sid, "message": {**body, "term_sheets": [{"terms": t} for t in fixed]} if fixed else
                {"subject": body["subject"], "body": "Could you please send us your best terms?"}}

    # 6. late accept ----------------------------------------------------------------------------------------
    def _late_accept(self, case, threads):
        c_alt, c_open = _c_alt(case), self._open_c(case, threads)
        known, cand = math.inf, None
        for sid in _live(threads):
            ev, std = threads[sid], standard_terms(threads[sid])
            for s in _sheets(ev):
                if (t := s.get("terms") or {}).get("unit_price") is not None and must_haves_ok(case, t, std):
                    known = min(known, self._est_c(case, ev, t, std))
            sheet_id, t = standing(ev)
            if sheet_id and moves_left(case, ev) <= self.LATE_MESSAGES and t.get("unit_price") is not None and must_haves_ok(case, t, std):
                c = self._est_c(case, ev, t, std)
                if c < c_alt and c <= c_open:
                    cand = min(cand or (c, sid, sheet_id), (c, sid, sheet_id))
        if cand and cand[0] <= (1 + self.LATE_TOLERANCE) * known:
            return {"supplier_id": cand[1], "message": {"action": {"type": "accept", "term_sheet_id": cand[2]}}}
        return None

    # 3. cost-share anchor -----------------------------------------------------------------------------------
    @staticmethod
    def _share_factor(case):
        """1 - share x drop for the best index driver the case shows falling (index_paths < 0), else None."""
        paths = case["buyer"].get("index_paths") or {}
        hits = [c["material_share"] * -paths[c["series"]] for c in (case.get("term_options") or {}).get("index_clause", [])
                if c and paths.get(c["series"], 0) < 0]
        return 1 - max(hits) if hits else None

    def _price(self, case, events, p):
        if self.ANCHOR_BY_SHARE and not _mine(events) and not _health_at_stake(case) and (f := self._share_factor(case)):
            return max(ANCHOR_FLOOR * p, min(f * p, case["buyer"].get("current_unit_price") or p))
        return super()._price(case, events, p)

    # 2 + 5. third equivalent sheet / cash-short -------------------------------------------------------------
    @staticmethod
    def _cash_short(case, events):
        text = " ".join([*(m.get("body") or "" for m in _sup(events)), str(case.get("suppliers", ""))])
        return bool(CASH_SHORT.search(text))

    def _trade_sheet(self, case, events, std, main, p, pins, seen):
        """Same C as main with another lever: shorter payment days (or another contract length) for a lower price."""
        short = self.CASH_SHORT_OFFER and self._cash_short(case, events)
        levers = ("payment_days",) if short else ("payment_days", "contract_months") if self.THIRD_SHEET else ()
        opts, best = case.get("term_options") or {}, None
        cost = lambda t: total_cost(case, t, std)  # noqa: E731
        for f in levers:
            if f not in case["negotiable"] or f in pins or (_health_at_stake(case) and f not in FREE_LEVERS):
                continue
            for o in (o for o in opts.get(f, []) if o and o != main.get(f) and (f != "payment_days" or o < main[f])):
                t = satisfy_must_haves(case, {**main, f: o}, std)
                slope = cost({**t, "unit_price": t["unit_price"] + 1}) - cost(t)
                if t.get(f) != o or slope <= 0:
                    continue
                price = round(min(p, t["unit_price"] - (cost(t) - cost(main)) / slope - 0.01), 2)
                v = {**t, "unit_price": price}
                if price > 0.75 * p and v not in seen and v != main and (best is None or price > best["unit_price"]):
                    best = v
            if best:
                break
        return best

    def _sheets(self, case, events, std, theirs):
        out = super()._sheets(case, events, std, theirs)
        if out and (self.THIRD_SHEET or self.CASH_SHORT_OFFER):
            seen = [s["terms"] for m in _mine(events) for s in m.get("term_sheets") or []]
            if extra := self._trade_sheet(case, events, std, out[0], theirs["unit_price"], _pinned(events), seen):
                if (extra := complete_offer(case, extra)) not in out:
                    out.append(extra)
        return out

"""SimplifyAgent: slim reciprocal agent. Anchor, steady matched concessions, RFQ round-robin.

Every choice among candidate sheets is priced with cost.total_cost, over the five parts of C:
1. price: anchor 0.80 x theirs, steady concessions matched to theirs;
2. uncovered need: contract length and volume are the options with the lowest C (never leave need uncovered);
3. payment, freight, lead time: each negotiable lever takes its lowest-C option, unless the supplier pinned it;
4. quality and other: ppm commitment likewise, plus a second sheet with an index clause for a higher price;
5. the supplier's health (strategic / bottleneck goals with a relationship cost): C charges for leaving the supplier below a
   sustainable margin, but the buyer cannot estimate its full cost (should-cost exists for about half the parts and can exceed
   the price), so cost.total_cost sees 0 and the mock does not price it. Safer rule there, UNTESTED against the real penalty:
   anchor 0.90 and only levers that cost the supplier nothing (contract length, volume); payment, freight, lead time and
   quality stay at the supplier's own terms.

Closing, must-have and pin helpers are shared with reciprocal.py."""

import math

from ..cost import RELATIONSHIP_GOALS, complete_offer, total_cost
from ..docs import standard_terms
from ..guard import satisfy_must_haves
from ..play import closing_move, latest, moves_left
from .reciprocal import (
    ANCHOR,
    ANCHOR_FLOOR,
    FRAC0,
    FRAC_MAX,
    FRAC_STEP,
    KEEP,
    MATCH,
    MIN_STEP,
    MOVING_MIN,
    _c_alt,
    _live,
    _mine,
    _pinned,
    _sup,
    _tick,
    _valid,
    case_c_open,
    closing_accept,
)

EASED_ANCHOR = 0.90
STALL = 0.01  # the supplier's best C fell by less than this (x C) across its last two replies: it has stalled
GAP = 0.05  # then our offer rises until it is at most this far (x their C) below theirs
FREE_LEVERS = ("contract_months", "volume_per_year")  # cost the supplier nothing in cash
LEVERS = ("contract_months", "volume_per_year", "payment_days", "incoterm", "lead_time_days", "ppm_commitment")


def _health_at_stake(case):
    """C charges for the supplier's margin (strategic / bottleneck goal with a price per margin point)."""
    b = case["buyer"]
    return b.get("category_goal") in RELATIONSHIP_GOALS and bool(b.get("relationship_eur_per_point"))


class SimplifyAgent:
    _c_open = math.inf  # set per decision; our offer never costs more than the closing rule would accept

    def decide(self, case, threads):
        if not _live(threads):  # nothing to answer
            return {"supplier_id": next(iter(threads), None), "message": {"action": {"type": "walk_away"}}}
        if accept := closing_accept(case, threads):
            return accept
        live = [s for s in _live(threads) if moves_left(case, threads[s]) >= 1]
        open_ = [s for s in live if latest(threads[s]).get("status") not in ("final_offer", "agreed")]
        if not open_:
            return closing_move(case, threads)

        def key(s):  # keep every thread moving: fewest messages first, then the cheapest
            ev = threads[s]
            c = min((c for c, _ in _valid(case, ev, standard_terms(ev), math.inf, musts=False)), default=math.inf)
            return len(_mine(ev)), c

        sid = min(open_, key=key)
        # cap: the opening and the best standing sheet of any other open thread
        others = [c for s in open_ if s != sid for c, _ in _valid(case, threads[s], standard_terms(threads[s]), math.inf)]
        self._c_open = min([case_c_open(case, threads), *others])
        events = threads[sid]
        std = standard_terms(events)
        valid = _valid(case, events, std, math.inf) or _valid(case, events, std, math.inf, musts=False)  # a must-have breach is fixed in our sheet
        if not valid:  # no priced sheet to answer: ask for one, give up after 3 asks
            if len(_mine(events)) >= 3:
                return {"supplier_id": sid, "message": {"action": {"type": "walk_away"}}}
            return {"supplier_id": sid, "message": {"subject": case.get("title", "Our enquiry"), "body": "Could you please send us your quote?"}}
        _, best = min(valid, key=lambda v: v[0])
        sheets = self._sheets(case, events, std, best["terms"])
        if not sheets:  # nothing new left to offer: close on the best sheet, or give up
            return closing_move(case, threads)
        return {
            "supplier_id": sid,
            "message": {
                "subject": case.get("title", "Our proposal"),
                "body": "Thank you for your offer. We have moved on our side; please see our updated terms.",
                "term_sheets": [{"terms": t} for t in sheets],
            },
        }

    @staticmethod
    def _their_move(events):
        """How far the supplier's best price fell in its last message (0 if it did not)."""
        ps = [min(s["terms"]["unit_price"] for s in m["term_sheets"] if s["terms"].get("unit_price") is not None)
              for m in _sup(events) if any(s["terms"].get("unit_price") is not None for s in m["term_sheets"])]
        return max(0.0, ps[-2] - ps[-1]) if len(ps) >= 2 else 0.0

    @staticmethod
    def _stalled(case, events, std):
        """We have opened and the supplier's best C fell by < STALL across its last two replies (3+ priced messages)."""
        cs = [min(total_cost(case, t["terms"], std) for t in m["term_sheets"] if t["terms"].get("unit_price") is not None)
              for m in _sup(events) if any(t["terms"].get("unit_price") is not None for t in m["term_sheets"])]
        return bool(_mine(events)) and len(cs) >= 3 and cs[-3] - cs[-1] < STALL * cs[-3]

    def _price(self, case, events, p):
        mine = [m["term_sheets"][0]["terms"]["unit_price"] for m in _mine(events) if m.get("term_sheets") and m["term_sheets"][0]["terms"].get("unit_price")]
        if not mine:
            cur = case["buyer"].get("current_unit_price") or p
            return max(ANCHOR_FLOOR * p, min((EASED_ANCHOR if _health_at_stake(case) else ANCHOR) * p, cur))  # anchor; never pay more than now unless forced
        frac = min(FRAC_MAX, FRAC0 + FRAC_STEP * len(mine))
        move = self._their_move(events)
        step = max(frac * (p - mine[-1]), MIN_STEP * p, _tick(p))
        if move > 0:  # they moved: answer in step, not beyond (a supplier that holds still gets the full step)
            step = max(MOVING_MIN * p, _tick(p), min(step, MATCH * move))
        top = p if moves_left(case, events) <= 2 else p * (1 - KEEP)
        return max(mine[-1], min(top, mine[-1] + step))

    def _sheets(self, case, events, std, theirs):
        p, pins = theirs["unit_price"], _pinned(events)
        base = {k: v for k, v in {**{f: std[f] for f in case["negotiable"] if f in std}, **theirs}.items() if v is not None}
        opts = case.get("term_options") or {}
        c_alt = _c_alt(case)
        sent = [m["term_sheets"] for m in _mine(events) if m.get("term_sheets")]
        seen = [s["terms"] for ss in sent for s in ss]

        def make(price, **over):
            over = {k: v for k, v in over.items() if k not in pins}
            return satisfy_must_haves(case, {**base, "unit_price": round(price, 2), **over}, std)

        def cost(t):
            return total_cost(case, t, std)

        def cap(t):  # hard floor: never offer a sheet that costs more than the alternative
            if (c := cost(t)) >= c_alt:
                slope = cost({**t, "unit_price": t["unit_price"] + 1}) - c
                if slope > 0:
                    t = {**t, "unit_price": round(t["unit_price"] - (c - c_alt) / slope - 0.01, 2)}
            return t

        def one(price):  # one sheet: for each negotiable lever the option with the lowest C (pinned ones stay theirs)
            over = {}
            for f in FREE_LEVERS if _health_at_stake(case) else LEVERS:
                options = [o for o in opts.get(f, []) if o] if f in case["negotiable"] and f not in pins else []
                if options:
                    over[f] = min(options, key=lambda o: cost(make(price, **over, **{f: o})))
            return cap(make(price, **over))

        price = self._price(case, events, p)
        main = one(price)
        floor = max((x["terms"]["unit_price"] for ss in sent for x in ss[:1] if x["terms"].get("unit_price")), default=0.0)
        while (main in seen or main["unit_price"] <= floor) and price < p:  # always a visible step, never a repeat, never above theirs
            price = min(p, price + _tick(p))
            new = one(price)
            if new == main:  # capped: the price cannot move
                break
            main = new
        if self._stalled(case, events, std):  # close the gap to <= GAP of their C, never past c_open
            f = lambda x: cost(one(x))
            target, lo, hi = (1 - GAP) * cost(theirs), main["unit_price"], p
            if f(hi) >= target:  # smallest price that reaches the target
                for _ in range(30):
                    mid = (lo + hi) / 2
                    lo, hi = (lo, mid) if f(mid) >= target else (mid, hi)
            if f(hi) > self._c_open:  # largest price that stays within c_open
                lo = main["unit_price"]
                for _ in range(30):
                    mid = (lo + hi) / 2
                    lo, hi = (mid, hi) if f(mid) <= self._c_open else (lo, mid)
                hi = lo
            hi = round(hi, 2)
            while hi > main["unit_price"] and f(hi) > self._c_open:  # rounding must not pass c_open
                hi = round(hi - 0.01, 2)
            if hi > main["unit_price"]:
                main = one(hi)
        if main in seen:
            return []
        out, variants = [main], []
        # the index clause is security for them, not cash: offer it at the price where our C stays just below main's
        clauses = (c for c in opts.get("index_clause", []) if c) if "index_clause" in case["negotiable"] and "index_clause" not in pins else []
        # the clause (deadband) with the lowest C at main's price is tried first: equal prices after the cap must not pick deadband 0
        for clause in sorted(clauses, key=lambda c: cost(make(main["unit_price"], index_clause=c, **{f: main[f] for f in LEVERS if f in main}))):
            t = make(main["unit_price"], index_clause=clause, **{f: main[f] for f in LEVERS if f in main})
            slope = cost({**t, "unit_price": t["unit_price"] + 1}) - cost(t)
            if t["index_clause"] == clause != main.get("index_clause") and slope > 0:
                price = round(max(0.75 * p, min(p, t["unit_price"] - (cost(t) - cost(main)) / slope - 0.01)), 2)  # no lowball
                v = cap({**t, "unit_price": price})
                if v not in seen and cost(v) < cost(main):
                    variants.append(v)
        if variants:
            out.append(max(variants, key=lambda v: v["unit_price"]))  # max keeps the first (lowest-C clause) on ties
        return [complete_offer(case, t) for t in out]

"""Target deals: for every real practice case we ran, which term sheet hits C_best, and why we missed it.

Run from the repo's agent/ folder:  uv run python <this file>
Reads only local files (cases, run dumps, data package); writes targets.md next to itself.
"""

import csv
import glob
import itertools
import json
import math
import os
import sys
from pathlib import Path

sys.path.insert(0, "/Users/nikolaydidiletsov/Documents/Codex/MUCHackatonFinal/agent")
from arena_kit.cost import RELATIONSHIP_GOALS, _years, closing_terms, must_haves_ok, supplier_value, total_cost  # noqa: E402

AGENT = Path("/Users/nikolaydidiletsov/Documents/Codex/MUCHackatonFinal/agent/arena_kit/sim_cases")
DATA = Path(os.environ.get("ARENA_DATA") or Path.home() / "Documents/Codex/negotiation-arena-kit/data")
OUT = Path(__file__).with_name("targets.md")
RUN_DIRS = ["real_runs", "real_runs_v16", "real_runs_v17"]  # oldest to newest
# supplier standard terms seen in the replays (arena result terms / "our standard Zahlungsziel" in the e-mails)
STD_PPM = {"sup:70110": 900, "sup:70510": 250, "sup:70530": 350, "sup:70620": 150, "sup:70210": 1200, "sup:70240": 1400,
           "sup:70610": 80, "sup:70710": 50, "sup:70410": 300, "sup:70140": 1500, "sup:70740": 70}  # sup:70250 unknown -> 0
STD_PAY = {"sup:70240": 45, "sup:70140": 60}  # all others say 30 days net


def load_json(p):
    return json.loads(Path(p).read_text(encoding="utf-8"))


def suppliers_csv():
    with open(DATA / "data/suppliers.csv", encoding="utf-8") as fh:
        return {r["id"]: r for r in csv.DictReader(fh)}


def standard(sid, sup_rows):
    row = sup_rows.get(sid, {})
    std = {"payment_days": STD_PAY.get(sid, 30), "ppm_commitment": STD_PPM.get(sid, 0), "chargeback_eur_per_complaint": 0,
           "tooling_eur": 0, "incoterm": row.get("incoterm") or "DAP"}
    if row.get("standard_lead_time_days"):
        std["lead_time_days"] = int(row["standard_lead_time_days"])
    return std


def inv_soft(s):
    """margin points below sustainable that cost `s` (cost.py _soft inverted)."""
    return math.sqrt(10 * s) if s <= 2.5 else s + 2.5


def fit_supplier(case, sid, dumps, std, facts):
    """(full_cost, interest_rate, how) from the arena's own relationship terms in the dumps."""
    b = case["buyer"]
    pts = [(d["result"]["terms"], d["result"]["cost_breakdown"]["relationship"]) for d in dumps
           if d["result"].get("deal") and d["result"].get("supplier_id") == sid and d["result"]["cost_breakdown"].get("relationship", 0) > 0]
    should = next((v["unit_cost"] for k, v in facts.items() if k.startswith("cost:" + case["parts"][0].split(":")[1])), None)
    if not pts:
        return should, 0.08, f"no arena health term observed: should-cost {should} and rate 0.08 assumed"
    best = None
    for rate in [x / 1000 for x in range(40, 141)]:
        sup = {"standard": std, "interest_rate": rate}
        fcs = []
        for t, rel in pts:
            years = _years(case, closing_terms(case, t, std))
            margin = b["sustainable_margin_pct"] - inv_soft(rel / (b["relationship_eur_per_point"] * years))
            fcs.append(supplier_value(case, t, sup) * (1 - margin / 100))
        spread = max(fcs) - min(fcs)
        if best is None or spread < best[0]:
            best = (spread, rate, sum(fcs) / len(fcs))
    spread, rate, fc = best
    how = f"fitted on {len(pts)} arena result(s): full_cost {fc:.2f} (spread {spread:.2f}), rate {rate:.3f}; should-cost {should}"
    if len(pts) == 1:
        rate = 0.08
        how = f"fitted on 1 arena result at rate 0.08 assumed: full_cost {fc:.2f}; should-cost {should}"
    return fc, rate, how


def cost(case, terms, std, sup):
    return total_cost(case, terms, std, sup)


def solve_price(case, fixed, std, sup, target, p_hi):
    """(highest unit_price with C <= target on these non-price terms or None, (lowest C reachable, its price))."""
    c0, c1 = cost(case, {**fixed, "unit_price": 0.0}, std, None), cost(case, {**fixed, "unit_price": 1.0}, std, None)
    p_lin = (target - c0) / (c1 - c0)  # linear without the health term
    if sup is None:
        return p_lin, (target, p_lin)
